use vstd::prelude::*;

verus! {

spec fn seq_contains(s: Seq<i32>, e: i32) -> bool {
    exists|i: int| 0 <= i < s.len() && s[i] == e
}

spec fn has_common(s1: Seq<i32>, s2: Seq<i32>) -> bool {
    exists|x: i32| seq_contains(s1, x) && seq_contains(s2, x)
}

fn contains(list: &Vec<i32>, element: i32) -> (res: bool)
    ensures
        res == seq_contains(list@, element),
{
    for &x in list.iter()
        invariant
            // Elements already iterated over do not contain `element`
            forall|i: int| 0 <= i < list@.len() - list.iter().len()
                ==> list@[i] != element,
        ensures
            res == seq_contains(list@, element),
    {
        if x == element {
            return true;
        }
    }
    false
}

fn has_common_element(list1: &Vec<i32>, list2: &Vec<i32>) -> (res: bool)
    ensures
        res == has_common(list1@, list2@),
{
    // Iterate over the smaller list to reduce work.
    if list1.len() <= list2.len() {
        for &x in list1.iter()
            invariant
                // No common element among the already-checked prefix of list1 and all of list2
                forall|i: int|
                    0 <= i < list1@.len() - list1.iter().len()
                    ==> !seq_contains(list2@, list1@[i]),
            ensures
                res == has_common(list1@, list2@),
        {
            if contains(list2, x) {
                return true;
            }
        }
    } else {
        for &x in list2.iter()
            invariant
                // No common element among the already-checked prefix of list2 and all of list1
                forall|i: int|
                    0 <= i < list2@.len() - list2.iter().len()
                    ==> !seq_contains(list1@, list2@[i]),
            ensures
                res == has_common(list1@, list2@),
        {
            if contains(list1, x) {
                return true;
            }
        }
    }
    false
}

}

